package de.privacyguard.adhook.imported.shield;
import android.app.Activity;import android.content.ClipData;import android.content.ClipboardManager;import android.content.pm.*;import android.os.Build;import android.os.Bundle;import android.view.Gravity;import android.widget.*;import java.security.MessageDigest;import java.util.Locale;
/** Shows current FX signer; does not reuse the legacy APK's incompatible fixed-signer exit gate. */
public final class FxYulongIntegrityActivity extends Activity{
 private String report="";private int dp(float n){return(int)(n*getResources().getDisplayMetrics().density+0.5f);}private TextView t(String s,int z,int c,boolean b){TextView v=new TextView(this);v.setText(s);v.setTextSize(z);v.setTextColor(c);if(b)v.setTypeface(null,android.graphics.Typeface.BOLD);v.setPadding(dp(4),dp(6),dp(4),dp(6));return v;}private Button b(String s,Runnable r){Button x=new Button(this);x.setAllCaps(false);x.setText(s);x.setOnClickListener(v->r.run());return x;}
 @Override protected void onCreate(Bundle saved){super.onCreate(saved);LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setBackgroundColor(0xfff7f8fa);LinearLayout h=new LinearLayout(this);h.setGravity(Gravity.CENTER_VERTICAL);h.setPadding(dp(10),dp(6),dp(10),dp(6));h.addView(b("‹ 返回安全护盾",this::finish));h.addView(t("应用签名与完整性",18,0xff17212b,true),new LinearLayout.LayoutParams(0,-2,1));root.addView(h);ScrollView sc=new ScrollView(this);LinearLayout body=new LinearLayout(this);body.setOrientation(1);body.setPadding(dp(14),dp(8),dp(14),dp(20));sc.addView(body);root.addView(sc,new LinearLayout.LayoutParams(-1,0,1));report=build();body.addView(t("FX 当前安装包签名指纹",18,0xff17212b,true));body.addView(t(report,13,0xff334155,false));body.addView(t("原版 PiracyWarningActivity 校验游龙原 APK 专属证书。合入 FX 后包名和签名证书已改变，不能沿用旧固定指纹，否则会误锁正式 FX。本页展示当前 FX 安装包身份，不执行反盗版强制退出。",12,0xff8a5b12,false));body.addView(b("复制签名报告",()->{ClipboardManager c=(ClipboardManager)getSystemService(CLIPBOARD_SERVICE);if(c!=null)c.setPrimaryClip(ClipData.newPlainText("FX signer",report));}));setContentView(root);}
 private String build(){StringBuilder o=new StringBuilder("Package: ").append(getPackageName()).append('\n');try{PackageInfo p;if(Build.VERSION.SDK_INT>=33)p=getPackageManager().getPackageInfo(getPackageName(),PackageManager.PackageInfoFlags.of(PackageManager.GET_SIGNING_CERTIFICATES));else p=getPackageManager().getPackageInfo(getPackageName(),PackageManager.GET_SIGNING_CERTIFICATES);o.append("Version: ").append(p.versionName).append('\n');if(Build.VERSION.SDK_INT>=28&&p.signingInfo!=null){SigningInfo si=p.signingInfo;Signature[] sig=si.hasMultipleSigners()?si.getApkContentsSigners():si.getSigningCertificateHistory();for(int i=0;sig!=null&&i<sig.length;i++)o.append("Signer ").append(i+1).append(" SHA-256: ").append(hex(MessageDigest.getInstance("SHA-256").digest(sig[i].toByteArray()))).append('\n');}else if(p.signatures!=null)for(Signature sig:p.signatures)o.append("Signer SHA-256: ").append(hex(MessageDigest.getInstance("SHA-256").digest(sig.toByteArray()))).append('\n');}catch(Throwable e){o.append("Signature read failed: ").append(e.getClass().getSimpleName());}return o.toString();}
 private String hex(byte[] a){StringBuilder s=new StringBuilder();for(byte x:a)s.append(String.format(Locale.ROOT,"%02X",x));return s.toString();}
}
